query.base:
TS metrics-gcp.cloudstorage.otel-default
// Scope to Cloud Storage; this data stream carries every GCP service the receiver collects.
| WHERE resource.attributes.gcp.resource_type == "gcs_bucket"
    AND `metrics.storage.googleapis.com/api/request_count` IS NOT NULL
// Split the rule's 4h window into a 1h "recent" slice and a 3h baseline. Adjust both the slice here
// and timeWindowSize together: a longer baseline is steadier, a shorter recent slice reacts faster.
| EVAL is_recent = @timestamp >= NOW() - 1 hour
| EVAL is_denied = attributes.response_code IN ("PERMISSION_DENIED", "UNAUTHENTICATED")
// request_count is a ~60s delta counter stored as a gauge. SUM_OVER_TIME totals each series and SUM
// adds the series together: the collector can split one bucket's metric across several series
// (_metric_names_hash is a dimension), and each sample is still counted once. Never RATE() it.
// Computing the denied count and the total in one STATS keeps the ratio correct regardless of
// document layout.
| STATS recent_denied   = SUM(SUM_OVER_TIME(`metrics.storage.googleapis.com/api/request_count`)) WHERE is_denied AND is_recent,
        recent_total    = SUM(SUM_OVER_TIME(`metrics.storage.googleapis.com/api/request_count`)) WHERE is_recent,
        baseline_denied = SUM(SUM_OVER_TIME(`metrics.storage.googleapis.com/api/request_count`)) WHERE is_denied AND NOT is_recent,
        baseline_total  = SUM(SUM_OVER_TIME(`metrics.storage.googleapis.com/api/request_count`)) WHERE NOT is_recent,
        denied_methods  = VALUES(attributes.method) WHERE is_denied AND is_recent,
        denied_codes    = VALUES(attributes.response_code) WHERE is_denied AND is_recent
    BY resource.attributes.bucket_name, resource.attributes.location
| EVAL recent_denied = COALESCE(recent_denied, 0), baseline_denied = COALESCE(baseline_denied, 0)

breach.segment:
// Require enough traffic in both slices for the comparison to mean anything.
WHERE recent_total >= 200 AND baseline_total >= 600 AND recent_denied >= 20
// Cast before dividing: request_count is a long and `a / b` would be integer division. Comparing
// shares rather than raw counts means ordinary traffic growth does not trip the rule.
| EVAL recent_denied_pct   = ROUND(recent_denied::DOUBLE / recent_total * 100.0, 3),
       baseline_denied_pct = ROUND(baseline_denied::DOUBLE / baseline_total * 100.0, 3)
// Step-change test. The `+ 1.0` sets a floor so a bucket with a zero baseline needs to reach ~1%
// before it alerts. Raise the multiplier for workloads that legitimately probe for access.
| WHERE recent_denied_pct > (baseline_denied_pct * 3.0) + 1.0
| SORT recent_denied DESC
| LIMIT 50
